/**
 * The daily briefing: what moved, what is due, what to do next, and why.
 *
 * Three sections, and the order is the point. Progress first, because seeing
 * what you did is what makes the rest bearable. Reminders second, because a
 * missed date costs more than a missed opportunity. Suggestions last, each
 * carrying the reason it is the next thing — the product's job is to make
 * someone who has never run a search run a good one, and a list of tasks with
 * no reasoning teaches nobody anything.
 *
 * Everything here is derived. Nothing is stored, nothing is generated by a
 * model, and every number can be traced to rows in the database, so the
 * briefing cannot drift from the work.
 */
import { and, eq, isNotNull, lte } from "drizzle-orm";
import type { Db } from "@/lib/db/client";
import { candidates, searchProjects, tasks } from "@/lib/db/schema";
import {
  computeNextBestActions,
  type NextBestAction,
} from "@/lib/domain/next-best-action";
import { COACHING, craftNoteFor } from "@/lib/domain/coaching";
import { noticeDueAt } from "@/lib/domain/profile-links";
import { buildProjectSnapshot } from "./search-projects";
import { dayEvents, shiftDay, type DayEvent } from "./daily";
import {
  beliefPrompt,
  staleBeliefs,
  type BeliefReminder,
} from "./hsal-briefing";

export interface ProgressLine {
  icon: string;
  text: string;
}

export interface Reminder {
  id: string;
  tone: "bad" | "warn" | "neutral";
  icon: string;
  title: string;
  detail: string;
  href: string;
  /** Days late. Negative means it is not due yet. */
  overdueDays: number;
}

export interface Suggestion extends NextBestAction {
  projectId: string;
  projectName: string;
  why?: string;
  good?: string;
}

export interface DailyBriefing {
  day: string;
  progress: ProgressLine[];
  /** One sentence summarising the day against the one before. */
  summary: string;
  reminders: Reminder[];
  suggestions: Suggestion[];
  /**
   * Beliefs recorded on the Diagnosis page that nobody has revisited. Empty
   * whenever HSAL is off or unreachable, which is most installs — it adds,
   * it is never required.
   */
  beliefs: BeliefReminder[];
  craftNote: string;
}

const EVENT_WORDS: Record<DayEvent["kind"], [string, string]> = {
  job: ["job opened", "jobs opened"],
  person: ["person added", "people added"],
  stage: ["pipeline move", "pipeline moves"],
  source: ["address kept", "addresses kept"],
  learning: ["learning recorded", "learnings recorded"],
};

const EVENT_ICON: Record<DayEvent["kind"], string> = {
  job: "💼",
  person: "👤",
  stage: "🪜",
  source: "🔗",
  learning: "📚",
};

function countByKind(events: DayEvent[]): Map<DayEvent["kind"], number> {
  const counts = new Map<DayEvent["kind"], number>();
  for (const event of events) {
    counts.set(event.kind, (counts.get(event.kind) ?? 0) + 1);
  }
  return counts;
}

/** Whole days between two ISO timestamps, positive when the first is later. */
function daysBetween(later: string, earlier: string): number {
  const ms = new Date(later).getTime() - new Date(earlier).getTime();
  return Math.floor(ms / 86_400_000);
}

/**
 * What is late, or about to be. Ordered by how late, because the thing you
 * are furthest behind on is the thing to do first — not the thing that
 * happens to be at the top of a list.
 */
export async function dailyReminders(db: Db, day: string): Promise<Reminder[]> {
  const asOf = `${day}T23:59:59.999Z`;
  const out: Reminder[] = [];
  const projects = await db.select().from(searchProjects);
  const projectName = new Map(projects.map((row) => [row.id, row.name]));

  const dueFollowUps = await db
    .select()
    .from(candidates)
    .where(
      and(
        isNotNull(candidates.nextActionDue),
        lte(candidates.nextActionDue, asOf),
      ),
    );
  for (const person of dueFollowUps) {
    const overdue = daysBetween(asOf, person.nextActionDue!);
    out.push({
      id: `follow-up:${person.id}`,
      tone: overdue > 3 ? "bad" : "warn",
      icon: "⏰",
      title: person.nextAction || "Follow up",
      detail: `${person.name} · ${projectName.get(person.searchProjectId) ?? ""}${
        overdue > 0
          ? ` · ${overdue} day${overdue === 1 ? "" : "s"} late`
          : " · due today"
      }`,
      href: `/searches/${person.searchProjectId}/candidates/${person.id}`,
      overdueDays: overdue,
    });
  }

  const openTasks = await db
    .select()
    .from(tasks)
    .where(and(eq(tasks.status, "open"), isNotNull(tasks.dueAt)));
  for (const task of openTasks) {
    if (!task.dueAt || task.dueAt > asOf) continue;
    const overdue = daysBetween(asOf, task.dueAt);
    out.push({
      id: `task:${task.id}`,
      tone: overdue > 3 ? "bad" : "warn",
      icon: "✅",
      title: task.title,
      detail: task.searchProjectId
        ? (projectName.get(task.searchProjectId) ?? "")
        : "No search",
      href: task.searchProjectId
        ? `/searches/${task.searchProjectId}`
        : "/tasks",
      overdueDays: overdue,
    });
  }

  /**
   * The one deadline that is a legal duty rather than a preference: a person
   * whose details you hold and have not told about it. It is surfaced here
   * because it is the reminder most easily forgotten and the most expensive
   * to miss (D-035).
   */
  const unnotified = await db.select().from(candidates);
  for (const person of unnotified) {
    if (person.noticeResolution) continue;
    const due = noticeDueAt(person.createdAt);
    if (due > asOf) continue;
    const overdue = daysBetween(asOf, due);
    out.push({
      id: `notice:${person.id}`,
      tone: overdue > 0 ? "bad" : "warn",
      icon: "📬",
      title: `Tell ${person.name} you hold their details`,
      detail: `A month from adding them · ${
        projectName.get(person.searchProjectId) ?? ""
      }${overdue > 0 ? ` · ${overdue} day${overdue === 1 ? "" : "s"} past` : " · due today"}`,
      href: `/searches/${person.searchProjectId}/candidates/${person.id}`,
      overdueDays: overdue,
    });
  }

  return out.sort((a, b) => b.overdueDays - a.overdueDays).slice(0, 12);
}

/**
 * The next moves across every open search, ranked, each with its reason.
 *
 * Three caps, and each one exists because of a way the list goes wrong.
 * Two per search, so one neglected search cannot fill the day. Two per kind
 * of move, because a workspace holding six barely-started searches otherwise
 * offers "extract role intelligence" six times and buries the one search
 * with people in it. Eight overall, because a list nobody finishes is a list
 * nobody starts.
 *
 * Within a priority, searches with people and recent movement come first: the
 * work you are actually doing outranks the work you have not begun.
 */
export async function dailySuggestions(db: Db): Promise<Suggestion[]> {
  const open = await db
    .select()
    .from(searchProjects)
    .where(eq(searchProjects.status, "open"));

  const scored: { suggestion: Suggestion; activity: number }[] = [];
  for (const project of open) {
    const snapshot = await buildProjectSnapshot(db, project.id);
    // A rough measure of "is this search alive", not a score about quality.
    const activity =
      snapshot.candidateCount * 3 +
      snapshot.queryCount +
      snapshot.channelCount +
      snapshot.outreachSent * 2;
    for (const action of computeNextBestActions(snapshot).slice(0, 2)) {
      const coaching = COACHING[action.id];
      scored.push({
        activity,
        suggestion: {
          ...action,
          projectId: project.id,
          projectName: project.name,
          why: coaching?.why,
          good: coaching?.good,
        },
      });
    }
  }

  scored.sort(
    (a, b) =>
      a.suggestion.priority - b.suggestion.priority ||
      b.activity - a.activity ||
      a.suggestion.projectName.localeCompare(b.suggestion.projectName),
  );

  const perKind = new Map<string, number>();
  const out: Suggestion[] = [];
  for (const entry of scored) {
    const seen = perKind.get(entry.suggestion.id) ?? 0;
    if (seen >= 2) continue;
    perKind.set(entry.suggestion.id, seen + 1);
    out.push(entry.suggestion);
    if (out.length >= 8) break;
  }
  return out;
}

/** One sentence on the day, honest when the day was quiet. */
export function progressSummary(
  today: DayEvent[],
  yesterday: DayEvent[],
): string {
  if (today.length === 0) {
    return yesterday.length > 0
      ? `Nothing recorded today. Yesterday had ${yesterday.length}, so the machinery works.`
      : "Nothing recorded today or yesterday. Quiet stretches happen; they are only a problem in a row.";
  }
  const change = today.length - yesterday.length;
  const direction =
    change > 0
      ? `${change} more than yesterday`
      : change < 0
        ? `${Math.abs(change)} fewer than yesterday`
        : "the same as yesterday";
  return `${today.length} thing${today.length === 1 ? "" : "s"} moved today, ${direction}.`;
}

export async function dailyBriefing(
  db: Db,
  day: string,
): Promise<DailyBriefing> {
  const today = dayEvents(db, day);
  const yesterday = dayEvents(db, shiftDay(day, -1));
  const counts = countByKind(today);

  const progress: ProgressLine[] = [...counts].map(([kind, count]) => {
    const [one, many] = EVENT_WORDS[kind];
    return {
      icon: EVENT_ICON[kind],
      text: `${count} ${count === 1 ? one : many}`,
    };
  });

  return {
    day,
    progress,
    summary: progressSummary(today, yesterday),
    reminders: await dailyReminders(db, day),
    suggestions: await dailySuggestions(db),
    beliefs: await staleBeliefs(db, `${day}T23:59:59.999Z`),
    craftNote: craftNoteFor(day),
  };
}

export { beliefPrompt };
export type { BeliefReminder };
